class Solution {
public:
    bool hasSpecialSubstring(string s, int k) {
        int n = s.size();
        for (int i = 0; i + k <= n; i++) {
            bool same = true;
            for (int j = i; j < i + k; j++) if (s[j] != s[i]) { same = false; break; }
            if (!same) continue;
            if ((i == 0 || s[i - 1] != s[i]) && (i + k == n || s[i + k] != s[i])) return true;
        }
        return false;
    }
};

