    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        i = 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            if j - i == k and (i == 0 or s[i - 1] != s[i]) and (j == n or s[j] != s[i]):
                return True
            i = j
        return False

